// Checkout conversion fix: ensure paidEvents increment on successful payment
// This module intercepts the checkout completion webhook and increments revenue counter

const fs = require('fs');
const path = require('path');

const REVENUE_FILE = path.join(__dirname, '..', 'data', 'revenue.json');

function incrementPaidEvents() {
  try {
    let data = { paidEvents: 0, conversionRate: 0, leads: 0 };
    if (fs.existsSync(REVENUE_FILE)) {
      data = JSON.parse(fs.readFileSync(REVENUE_FILE, 'utf8'));
    }
    data.paidEvents = (data.paidEvents || 0) + 1;
    data.conversionRate = data.leads > 0 ? (data.paidEvents / data.leads) * 100 : 0;
    fs.writeFileSync(REVENUE_FILE, JSON.stringify(data, null, 2));
    console.log('Checkout conversion: paidEvents incremented to', data.paidEvents);
    return true;
  } catch (err) {
    console.error('Checkout conversion error:', err);
    return false;
  }
}

// Hook into checkout completion (assumes webhook endpoint calls this)
module.exports = { incrementPaidEvents };
